import { useSmallMemoryBudget } from "./renderBudget.js";
import { resolveCornerStyle, resolveSurfaceId } from "./config.js";
import { getRefractionDirectionId, resolveRefractionEdgeFade } from "./refractionBounds.js";
import type { GlassCornerStyle, GlassSurface, LiquidGlassOptions } from "./types.js";

const WASM_SIMD_BASE64 =
    "";

export interface WasmDisplacementResult {
    blob: Blob;
    maxDisplacement: number;
}

interface WasmGlassExports {
    memory: WebAssembly.Memory;
    initTables(): void;
    getBmpOffset?(): number;
    getMaxDisplacementOffset?(): number;
    generateDisplacementBmp(
        targetW: number,
        targetH: number,
        radius: number,
        clampedBezel: number,
        glassThickness: number,
        scaleFactor: number,
        ior: number,
        surfaceId: number,
        flags: number,
    ): number;
    generateDirectionalDisplacementBmp(
        ...args: [...Parameters<WasmGlassExports["generateDisplacementBmp"]>, direction: number, edgeFade: number]
    ): number;
}

let wasmExports: WasmGlassExports | null = null;
let wasmF32View: Float32Array | null = null;
let wasmBmpU8View: Uint8Array | null = null;
let wasmMaxDisplacementOffset = 0x00020;
let wasmReady = false;
let wasmInitAttempted = false;

const wasmReadyCallbacks: Array<() => void> = [];

const MAX_DISPLACEMENT_CACHE_ENTRIES = 64;
export const MAX_DISPLACEMENT_TEXELS = 136_000;

function getMaxDisplacementCacheBytes(): number {
    return (useSmallMemoryBudget() ? 4 : 16) * 1024 * 1024;
}

interface CachedDisplacementEntry {
    readonly key: string;
    readonly blob: Blob;
    readonly maxDisplacement: number;
    readonly byteSize: number;
    blobUrl: string | null;
    blobUrlRefCount: number;
    evicted: boolean;
}

const displacementCache = new Map<string, CachedDisplacementEntry>();
const displacementByBlob = new WeakMap<Blob, CachedDisplacementEntry>();
const displacementByUrl = new Map<string, CachedDisplacementEntry>();
let displacementCacheBytes = 0;
let onBlobUrlEvicted: (() => void) | null = null;

export function setOnBlobUrlEvicted(callback: (() => void) | null): void {
    onBlobUrlEvicted = callback;
}

function evictDisplacementCacheIfNeeded(): void {
    const maxCacheBytes = getMaxDisplacementCacheBytes();
    if (
        displacementCache.size <= MAX_DISPLACEMENT_CACHE_ENTRIES &&
        displacementCacheBytes <= maxCacheBytes
    ) {
        return;
    }
    for (const [key, entry] of displacementCache) {
        if (
            displacementCache.size <= MAX_DISPLACEMENT_CACHE_ENTRIES &&
            displacementCacheBytes <= maxCacheBytes
        ) {
            break;
        }
        displacementCache.delete(key);
        displacementCacheBytes = Math.max(0, displacementCacheBytes - entry.byteSize);
        entry.evicted = true;
        if (entry.blobUrl && entry.blobUrlRefCount <= 0) {
            displacementByUrl.delete(entry.blobUrl);
            revokeBlobUrlSafely(entry.blobUrl);
            entry.blobUrl = null;
            onBlobUrlEvicted?.();
        }
    }
}

export function acquireCachedDisplacementBlobUrl(blob: Blob): {
    blobUrl: string;
    createdNew: boolean;
} {
    const entry = displacementByBlob.get(blob);
    if (entry) {
        if (entry.blobUrl) {
            entry.blobUrlRefCount++;
            return { blobUrl: entry.blobUrl, createdNew: false };
        }
        const blobUrl = URL.createObjectURL(blob);
        entry.blobUrl = blobUrl;
        entry.blobUrlRefCount = 1;
        displacementByUrl.set(blobUrl, entry);
        return { blobUrl, createdNew: true };
    }
    return { blobUrl: URL.createObjectURL(blob), createdNew: true };
}

export function releaseCachedDisplacementBlobUrl(blobUrl: string | null | undefined): boolean {
    if (!blobUrl) return false;
    const entry = displacementByUrl.get(blobUrl);
    if (!entry) {
        revokeBlobUrlSafely(blobUrl);
        return true;
    }
    if (entry.blobUrlRefCount > 0) {
        entry.blobUrlRefCount--;
    }
    if (entry.evicted && entry.blobUrlRefCount <= 0) {
        displacementByUrl.delete(blobUrl);
        revokeBlobUrlSafely(blobUrl);
        entry.blobUrl = null;
        return true;
    }
    return false;
}

export function clearDisplacementCache(): number {
    let revokedCount = 0;
    for (const entry of displacementCache.values()) {
        if (entry.blobUrl) {
            displacementByUrl.delete(entry.blobUrl);
            revokeBlobUrlSafely(entry.blobUrl);
            onBlobUrlEvicted?.();
            entry.blobUrl = null;
            revokedCount++;
        }
        entry.blobUrlRefCount = 0;
        entry.evicted = true;
    }
    displacementCache.clear();
    for (const [url, entry] of displacementByUrl) {
        revokeBlobUrlSafely(url);
        onBlobUrlEvicted?.();
        entry.blobUrl = null;
        entry.blobUrlRefCount = 0;
        revokedCount++;
    }
    displacementByUrl.clear();
    displacementCacheBytes = 0;
    return revokedCount;
}

export function getDisplacementCacheStats(): {
    entries: number;
    bytes: number;
    activeBlobUrls: number;
} {
    return {
        entries: displacementCache.size,
        bytes: displacementCacheBytes,
        activeBlobUrls: displacementByUrl.size,
    };
}

export function isWasmReady(): boolean {
    return wasmReady;
}

export function onWasmReady(callback: () => void): () => void {
    if (typeof callback !== "function") {
        return () => {};
    }
    if (wasmReady) {
        callback();
        return () => {};
    }
    wasmReadyCallbacks.push(callback);
    return () => {
        const index = wasmReadyCallbacks.indexOf(callback);
        if (index >= 0) {
            wasmReadyCallbacks.splice(index, 1);
        }
    };
}

function notifyWasmReady(): void {
    wasmReady = true;
    if (wasmReadyCallbacks.length === 0) return;
    const pending = wasmReadyCallbacks.splice(0, wasmReadyCallbacks.length);
    for (let index = 0; index < pending.length; index += 1) {
        try {
            pending[index]!();
        } catch (error) {
            console.error("[LiquidGlass] Error in wasmReady callback:", error);
        }
    }
}

function decodeBase64ToUint8(base64String: string): Uint8Array | null {
    if (typeof atob === "function") {
        const binaryString = atob(base64String);
        const length = binaryString.length;
        const bytes = new Uint8Array(length);
        for (let index = 0; index < length; index++) {
            bytes[index] = binaryString.charCodeAt(index);
        }
        return bytes;
    }
    if (typeof Buffer !== "undefined") {
        return new Uint8Array(Buffer.from(base64String, "base64"));
    }
    return null;
}

function bindWasmInstance(instance: WebAssembly.Instance): void {
    const exports = instance.exports as unknown as WasmGlassExports;
    wasmExports = exports;
    const bmpOffset =
        typeof exports.getBmpOffset === "function" ? exports.getBmpOffset() : 0x14c00;
    wasmMaxDisplacementOffset =
        typeof exports.getMaxDisplacementOffset === "function"
            ? exports.getMaxDisplacementOffset()
            : 0x00020;
    wasmF32View = new Float32Array(exports.memory.buffer);
    wasmBmpU8View = new Uint8Array(exports.memory.buffer, bmpOffset);
    exports.initTables();
    notifyWasmReady();
}

export function initWasmSimdModule(): void {
    if (wasmReady || wasmInitAttempted) return;
    wasmInitAttempted = true;
    try {
        if (typeof WebAssembly !== "object" || typeof WebAssembly.validate !== "function") {
            return;
        }
        const bytes = decodeBase64ToUint8(WASM_SIMD_BASE64);
        if (!bytes) return;

        const wasmBufferSource = (
            bytes.byteOffset === 0 && bytes.byteLength === bytes.buffer.byteLength
                ? bytes
                : bytes.slice()
        ) as BufferSource;

        if (!WebAssembly.validate(wasmBufferSource)) {
            return;
        }

        try {
            const module = new WebAssembly.Module(wasmBufferSource);
            const instance = new WebAssembly.Instance(module);
            bindWasmInstance(instance);
        } catch {
            WebAssembly.instantiate(wasmBufferSource)
                .then((result) => {
                    const instance =
                        "instance" in result
                            ? (result as { instance: WebAssembly.Instance }).instance
                            : (result as WebAssembly.Instance);
                    bindWasmInstance(instance);
                })
                .catch((error) => {
                    console.warn("[LiquidGlass] WASM async instantiation failed:", error);
                });
        }
    } catch {
    }
}

export function getWasmDisplacementBmp(
    targetW: number,
    targetH: number,
    radius: number,
    clampedBezel: number,
    thickness: number,
    effectiveScale: number,
    ior: number,
    surface: GlassSurface,
    pill: boolean,
    isAxisX: boolean,
    cornerStyle: GlassCornerStyle = "circular",
    refraction?: Pick<LiquidGlassOptions, "refractionDirection" | "refractionEdgeFade">,
): WasmDisplacementResult | null {
    if (
        !Number.isInteger(targetW) || !Number.isInteger(targetH) ||
        targetW <= 0 || targetH <= 0 || targetW * targetH > MAX_DISPLACEMENT_TEXELS
    ) {
        return null;
    }
    if (!wasmReady) {
        initWasmSimdModule();
    }
    if (!wasmReady || !wasmExports || !wasmBmpU8View || !wasmF32View) {
        return null;
    }

    if (wasmF32View.buffer.byteLength === 0 || wasmBmpU8View.buffer.byteLength === 0) {
        const bmpOffset =
            typeof wasmExports.getBmpOffset === "function" ? wasmExports.getBmpOffset() : 0x14c00;
        wasmF32View = new Float32Array(wasmExports.memory.buffer);
        wasmBmpU8View = new Uint8Array(wasmExports.memory.buffer, bmpOffset);
    }

    const surfaceId = resolveSurfaceId(surface);

    let flags = 0;
    if (pill) flags |= 1;
    if (isAxisX) flags |= 2;
    if (resolveCornerStyle(cornerStyle) === "squircle") flags |= 4;

    const direction = isAxisX ? 0 : getRefractionDirectionId(refraction?.refractionDirection);
    const edgeFade = direction === 0 ? 0 : Math.fround(resolveRefractionEdgeFade(refraction?.refractionEdgeFade));
    const cacheKey = `${targetW}|${targetH}|${Math.fround(radius)}|${Math.fround(clampedBezel)}|${Math.fround(thickness)}|${Math.fround(effectiveScale)}|${Math.fround(ior)}|${surfaceId}|${flags}|${direction}|${edgeFade}`;
    const cached = displacementCache.get(cacheKey);
    if (cached) {
        displacementCache.delete(cacheKey);
        displacementCache.set(cacheKey, cached);
        return {
            blob: cached.blob,
            maxDisplacement: cached.maxDisplacement,
        };
    }

    const bmpByteLength = wasmExports.generateDirectionalDisplacementBmp(
        targetW,
        targetH,
        radius,
        clampedBezel,
        thickness,
        effectiveScale,
        ior,
        surfaceId,
        flags,
        direction,
        edgeFade,
    );
    if (bmpByteLength <= 64) {
        return null;
    }

    if (wasmBmpU8View.buffer.byteLength === 0 || wasmF32View.buffer.byteLength === 0) {
        const bmpOffset =
            typeof wasmExports.getBmpOffset === "function" ? wasmExports.getBmpOffset() : 0x14c00;
        wasmF32View = new Float32Array(wasmExports.memory.buffer);
        wasmBmpU8View = new Uint8Array(wasmExports.memory.buffer, bmpOffset);
    }

    const bmpView = wasmBmpU8View.subarray(0, bmpByteLength);
    const blob = new Blob([bmpView as Uint8Array<ArrayBuffer>], { type: "image/bmp" });
    const maxDisplacement = wasmF32View[wasmMaxDisplacementOffset >> 2] || 1.0;

    const entry: CachedDisplacementEntry = {
        key: cacheKey,
        blob,
        maxDisplacement,
        byteSize: bmpByteLength,
        blobUrl: null,
        blobUrlRefCount: 0,
        evicted: false,
    };
    displacementCache.set(cacheKey, entry);
    displacementByBlob.set(blob, entry);
    displacementCacheBytes += bmpByteLength;
    evictDisplacementCacheIfNeeded();

    return { blob, maxDisplacement };
}

export function revokeBlobUrlSafely(url: string | null | undefined): void {
    if (!url || !url.startsWith("blob:")) return;
    if (typeof URL !== "undefined" && typeof URL.revokeObjectURL === "function") {
        URL.revokeObjectURL(url);
    }
}

export function resetWasmModuleForTesting(): void {
    wasmExports = null;
    wasmF32View = null;
    wasmBmpU8View = null;
    wasmReady = false;
    wasmInitAttempted = false;
    wasmReadyCallbacks.length = 0;
    clearDisplacementCache();
}
